SELECT COUNT(*) FROM 설계사 S
WHERE  S.설계사번호 NOT IN (SELECT 설계사번호 FROM 계약);
-- ②
SELECT COUNT(*) FROM 설계사 S
WHERE  NOT EXISTS (SELECT 1 FROM 계약 C WHERE C.설계사번호 = S.설계사번호);
-- ③
SELECT COUNT(*) FROM 설계사 S
WHERE  S.설계사번호 NOT IN (SELECT 설계사번호 FROM 계약
                            WHERE  설계사번호 IS NOT NULL);

-- ①
SELECT COUNT(*) FROM 계약
WHERE  월보험료 > ALL (SELECT 월보험료 FROM 계약 WHERE 상품코드 = 'P1');
-- ②
SELECT COUNT(*) FROM 계약
WHERE  월보험료 > ANY (SELECT 월보험료 FROM 계약 WHERE 상품코드 = 'P1');
-- ③
SELECT COUNT(*) FROM 계약
WHERE  월보험료 > ALL (SELECT 월보험료 FROM 계약 WHERE 상품코드 = 'P9');

-- ①
SELECT 지역, 상품코드, SUM(월보험료) FROM 계약 GROUP BY CUBE(지역, 상품코드);
-- ②
SELECT 지역, 상품코드, SUM(월보험료) FROM 계약 GROUP BY ROLLUP(지역, 상품코드);
-- ③
SELECT 지역, 상품코드, SUM(월보험료) FROM 계약
GROUP  BY GROUPING SETS ((지역), (상품코드), ());

